import { ParentSize } from '@visx/responsive';
import React, { forwardRef, PropsWithChildren } from 'react';

import { iterateSlots } from './functions/iterate-slots.js';
import { getScale } from './functions/scales.js';
import { Marker } from './slots/Marker.js';
import { Track } from './slots/Track.js';
import { AnnotationsChartProps } from './types/annotations-chart-props.js';
import { AnnotationsTimeseriesRenderer } from '../core/components/annotations-timeseries/AnnotationsTimeseriesRenderer.js';

const LABELS_OFFSET = 80;

export const _AnnotationsChart = /* @__PURE__ */ forwardRef<
  SVGSVGElement,
  PropsWithChildren<AnnotationsChartProps>
>((props, forwardedRef) => {
  const { annotationsActions, children, showLabels } = props;

  const { aggregatedAnnotations, tracks } = iterateSlots(children);

  return (
    <ParentSize parentSizeStyles={{ height: '100%', width: '100%' }}>
      {(parent) => {
        const labelsOffset = showLabels ? LABELS_OFFSET : 0;
        const scale = getScale(
          aggregatedAnnotations,
          parent.width - labelsOffset,
        );

        return (
          <AnnotationsTimeseriesRenderer
            width={parent.width}
            scale={scale}
            ref={forwardedRef}
            tracks={tracks}
            annotationsActions={annotationsActions}
            showLabels={showLabels}
            labelsOffset={labelsOffset}
          />
        );
      }}
    </ParentSize>
  );
});

export const AnnotationsChart = Object.assign(_AnnotationsChart, {
  Track,
  Marker,
});
